  showToolbar(tab){for(let b of $$('#ribbon-tabs button'))b.classList.toggle('active',b.dataset.tab===tab);$('#ribbon-tools').innerHTML=TOOLBARS[tab].map(id=>{if(!id)return '<span class="tool-divider"></span>';let c=this.commands.items.get(id);return `<button data-command="${id}" title="${c.label}${c.shortcut?' · '+c.shortcut:''}">${icon(c.icon)}<span>${escape(({zoomextents:'Fit',fourview:'4 views',select:'Select',new:'New',open:'Open',save:'Save',curve:'Curve',move:'Move',rotate:'Rotate',scale:'Scale',extrude:'Extrude',loft:'Loft',undo:'Undo',redo:'Redo'})[id]??c.label)}</span></button>`;}).join('')+'<span class="shortcut-hint">PRECISION MODELING</span>';}
