  getViewports(){let area=$('#viewport-area'),w=area.clientWidth,h=area.clientHeight;if(this.four){let hw=w/2,hh=h/2;return [{name:'Top',camera:this.cameras.Top,x:0,y:0,width:hw,height:hh},{name:'Perspective',camera:this.cameras.Perspective,x:hw,y:0,width:hw,height:hh},{name:'Front',camera:this.cameras.Front,x:0,y:hh,width:hw,height:hh},{name:'Right',camera:this.cameras.Right,x:hw,y:hh,width:hw,height:hh}];}return [{name:this.activeView,camera:this.cameras[this.activeView],x:0,y:0,width:w,height:h}];}
