  updatePreviews(){let list=this.graph.previewGeometry(),next=new Map();this.previews=list.map((entry,i)=>{let key=entry.node.id+':'+i,stamp=this.graph.cache.get(entry.node.id)?.stamp??0,previous=this.previewMap.get(key);if(previous?.stamp===stamp){next.set(key,previous);return previous.object;}let color=entry.node.type==='ribs'?'#4c776e':'#77a595',o=makeObject(entry.geometry,entry.node.label,'weave',color);o.id='preview_'+key;o.preview=true;o.nodeId=entry.node.id;o.revision=stamp;o.material={roughness:.42,metallic:.18};next.set(key,{stamp,object:o});this.doc.cache.delete(o.id);return o;});for(let [key,value] of this.previewMap)if(!next.has(key))this.doc.cache.delete(value.object.id);this.previewMap=next;this.rebuildScene();}
