  updateUI(){ $('#document-title').textContent=this.doc.name+'.veldra';document.title='Veldra 3D — '+this.doc.name;$('#document-object-count').textContent=this.doc.objects.length+' objects';$('#units-status').textContent=({mm:'Millimeters',cm:'Centimeters',m:'Meters',in:'Inches',ft:'Feet'})[this.doc.units];for(let [k,v] of Object.entries(this.flags))$('#toggle-'+k)?.classList.toggle('active',v);$('#selection-info').textContent=this.tool?this.toolPrompt():this.doc.selection.size?this.doc.selection.size+' selected'+(this.flags.points?' · Control points on':''):'';this.updateViewLabels();this.updateInspector();}
