  fit(selected){let b=selected&&this.doc.selection.size?this.doc.bounds(true):this.doc.bounds();if(!selected&&this.previews.length){let points=[b.min,b.max];for(let o of this.previews){let pb=this.doc.display(o).bounds;points.push(pb.min,pb.max);}let min=[0,1,2].map(i=>Math.min(...points.map(p=>p[i]))),max=[0,1,2].map(i=>Math.max(...points.map(p=>p[i])));b={min,max,center:V.mul(V.add(min,max),.5),size:V.sub(max,min)};}let vp=this.getViewports().find(v=>v.name===this.activeView)??this.getViewports()[0];vp.camera.fit(b,vp.width/vp.height);this.showCaption=false;this.updateViewLabels();this.invalidate();}
  toggle(name){this.flags[name]=!this.flags[name];if(name==='grid')this.renderer.grid=this.flags.grid;if(name==='points')this.selectedControl=null;this.updateUI();this.invalidate();}
  toggleWeave(){document.body.classList.toggle('weave-hidden');this.invalidate();if(!document.body.classList.contains('weave-hidden'))requestAnimationFrame(()=>this.graphView.fit());}
  setWorkspace(parametric){document.body.classList.remove('weave-hidden');document.body.classList.toggle('parametric-max',parametric);$('#model-workspace').classList.toggle('active',!parametric);$('#param-workspace').classList.toggle('active',parametric);requestAnimationFrame(()=>{this.graphView.fit();this.invalidate();});}
