  openFile(){$('#file-input').click();}
  async importFile(file){if(file.size>100*1024*1024)throw Error('File exceeds the 100 MB import budget');let ext=file.name.split('.').pop().toLowerCase();if(['veldra','json','weave'].includes(ext)){let data=JSON.parse(await file.text());if(data.format==='weave'){this.graphView.snapshot();this.graph.restore(data);this.graphView.fit();}else{let testDoc=new Document(),testGraph=new Graph(COMPONENTS);testDoc.restore(data);testGraph.restore(data.extra?.graph??{format:'weave',version:1,nodes:[],wires:[]});this.doc.restore(data);this.doc.undoStack=[];this.doc.redoStack=[];this.graph.restore(data.extra?.graph??{format:'weave',version:1,nodes:[],wires:[]});this.showCaption=false;this.graphView.fit();this.requestSolve();}toast('Opened '+file.name);return;}
    let imported;if(ext==='obj')imported=importOBJ(await file.text());else if(ext==='stl')imported={mesh:importSTL(await file.arrayBuffer())};else if(ext==='dxf')imported=importDXF(await file.text());else throw Error('Supported inputs: .veldra, .weave, OBJ, STL, and basic DXF.');this.doc.transaction('Import '+file.name,()=>{let ids=[];if(imported.mesh)ids.push(this.doc.add(imported.mesh,file.name).id);if(imported.lines?.length)ids.push(this.doc.add({kind:'lines',segments:imported.lines},file.name+' lines').id);for(let c of imported.curves??[])ids.push(this.doc.add(c,file.name+' curve').id);this.doc.select(ids);});this.fit(true);this.showCaption=false;
  }
  async newDocument(){let v=await formDialog('New document',[{key:'name',label:'Name',value:'Untitled',type:'text'}],{description:'Save your current document first to keep a separate copy. Creating a new document replaces the current autosaved workspace.',submit:'Create document'});if(!v)return;let d=new Document();d.name=v.name;this.doc.restore(d.serialize());this.doc.undoStack=[];this.doc.redoStack=[];this.graph.restore({format:'weave',version:1,nodes:[],wires:[]});this.graphView.select(null);this.showCaption=false;this.requestSolve();this.fit(false);}
  async loadDemo(){let v=await formDialog('Open canopy study',[],{description:'This replaces the current workspace. Save the current document first to retain a separate copy.',submit:'Open example'});if(!v)return;let currentDoc=this.doc,currentGraph=this.graph;this.setupDemoData();let data=this.doc.serialize(),graphData=this.graph.serialize();this.doc=currentDoc;this.graph=currentGraph;this.commands=new Commands(this);this.doc.restore(data);this.graph.restore(graphData);this.doc.undoStack=[];this.doc.redoStack=[];this.showCaption=true;this.cameras.Perspective=new Camera();this.graphView.select(null);this.graphView.fit();this.requestSolve();}
  bake(){try{let outputs=this.graph.previewGeometry();if(this.selectedNode){let selected=outputs.filter(e=>e.node.id===this.selectedNode);if(selected.length)outputs=selected;}if(!outputs.length)throw Error('Enable preview on a geometry-producing component first');let graphBefore=this.graph.serialize();this.doc.transaction('Bake Weave geometry',()=>{let layer=this.doc.layers.find(l=>l.id==='baked');if(!layer){layer={id:'baked',name:'Weave / baked',color:'#6f9b8c',visible:true,locked:false};this.doc.layers.push(layer);}let ids=outputs.map(e=>this.doc.add(structuredClone(e.geometry),e.node.label+' / baked',{layer:'baked',color:e.node.type==='ribs'?'#4c776e':'#77a595'}).id);this.doc.select(ids);});for(let {node} of outputs)node.preview=false;let history=this.doc.undoStack.at(-1);history.graphBefore=graphBefore;history.graphAfter=this.graph.serialize();this.graph.changed('preview');this.graphView.select(null);toast(`Baked ${outputs.length} editable objects. Their graph previews are now hidden.`);}catch(e){toast(e.message,true);}}
